import { chromium } from '@playwright/test'
const b=await chromium.launch({executablePath:'C:/Users/Administrator/AppData/Local/ms-playwright/chromium-1243/chrome-win64/chrome.exe'})
const pg=await b.newPage({viewport:{width:390,height:844}})
await pg.goto('http://127.0.0.1:8099/#/pages/inspection/index?kind=mid',{waitUntil:'domcontentloaded',timeout:25000}).catch(e=>console.log('goto',e.message))
await pg.waitForTimeout(2500)
// read labels and current desc + range max
const base = await pg.evaluate(()=>{
  const labels=[...document.querySelectorAll('.range-labels text')].map(t=>t.textContent.trim())
  const desc=(document.querySelector('.range-desc')||{}).textContent||''
  const inp=document.querySelector('input[type=range]')
  return {labels, desc, max: inp?inp.max:null, val: inp?inp.value:null}
})
console.log('initial:', JSON.stringify(base))
// set range to each value and read desc
for (const v of ['0','1','2','3','4']) {
  await pg.evaluate((val)=>{
    const inp=document.querySelector('input[type=range]')
    inp.value=val; inp.dispatchEvent(new Event('input',{bubbles:true}))
  }, v)
  await pg.waitForTimeout(200)
  const d = await pg.evaluate(()=>({desc:(document.querySelector('.range-desc')||{}).textContent||'', active:(document.querySelector('.range-labels .active')||{}).textContent||''}))
  console.log('val='+v, JSON.stringify(d))
}
// screenshot with val=1 (轻度)
await pg.evaluate(()=>{const inp=document.querySelector('input[type=range]'); inp.value='1'; inp.dispatchEvent(new Event('input',{bubbles:true}))})
await pg.waitForTimeout(300)
await pg.evaluate(()=>document.querySelector('.mid-bold').scrollIntoView({block:'center'}))
await pg.waitForTimeout(300)
await pg.screenshot({path:'D:/repository/_wd.png'})
await b.close()

